-- The previous migration (20261002124417_add_demand_clone_audit_fields) was generated by
-- `prisma migrate dev`'s schema diff, which does not know about
-- demand_assignments_one_active_owner_per_demand (a partial unique index, not representable
-- in schema.prisma's DSL — see the note in 20261001185211) and so it silently dropped it as
-- unrepresented drift. Recreated here, idempotently, so a fresh deploy replaying every
-- migration in order ends up with the index present, same as this dev database (which had it
-- restored directly — see IMPORTANT note in 20261001185211's migration.sql).
--
-- Enforces "at most one active account_manager / spoc per demand" — see migration
-- 20260924170125_split_demand_spoc_assignment for the original rationale.
CREATE UNIQUE INDEX IF NOT EXISTS "demand_assignments_one_active_owner_per_demand"
  ON "demand_assignments" ("demand_id", "role_in_demand")
  WHERE "is_active" = true AND "role_in_demand" IN ('account_manager', 'spoc');
